VALUES (
  '3562ce73-466d-4194-b4aa-ffc9bcb3057c',
  (SELECT "id" FROM "modelltests" WHERE "number" = 8),
  'HOEREN', 1, 'KURZANTWORT',
  'Hören', 'Sie hören fünf Ansagen am Telefon. Zu jedem Text gibt es eine Aufgabe. Ergänzen Sie die Telefonnotizen. Sie hören jeden Text zweimal.',
  5, 'AUTO', '{"media":{"transcript":"Beispiel: Guten Tag, Herr Hersel. Hier ist das Autohaus Unger. Sie können Ihr Auto morgen ab 8:30 Uhr hier abholen. Auf Wiederhören.\n\nNummer 1: Die gewünschte Nummer lautet 168 85 38, die Vorwahl ist 069. Wenn Sie eine weitere Nummer wünschen oder verbunden werden wollen, bleiben Sie bitte am Apparat.\n\nNummer 2: Mensch, Nana. Hier ist Dimitri. Jetzt rufe ich schon zum dritten Mal an und du bist immer noch nicht da. Wir sind doch heute Abend verabredet. Leider muss ich noch länger arbeiten, das heißt, wir können uns heute Abend nicht treffen. Aber passt es dir vielleicht morgen? Ruf mich doch bitte auf dem Handy an.\n\nNummer 3: Hallo, Ingo. Hier ist Sascha. Ich rufe an wegen des Computerkurses. Hast du einen Stift? Also, er findet statt am Dienstag um 18 Uhr, Raum 136. Ich warte am Eingang auf dich, ok?\n\nNummer 4: Also … Sie wollen morgen Mittag nach Köln. Hier ist Ihre Verbindung. Sie fahren um 11:45 Uhr ab Frankfurt und sind um 14:00 Uhr in Köln. Der Preis ohne Bahn-Card beträgt 45 Euro.\n\nNummer 5: Gudrun Stock, Firma Keller. Frau Stefanovic, wir wissen, dass Sie Urlaub haben, aber leider ist Frau Müller krank geworden. Können Sie nächste Woche vielleicht an zwei Tagen reinkommen, und zwar am Dienstagvormittag und Donnerstagnachmittag. Rufen Sie mich bitte auf jeden Fall zurück."}}'::jsonb,
  'a2-modelltest-1-hoeren-teil-1-v1', NULL, 1
);
