VALUES (
  'eb22fe67-a192-4eaa-ad5f-35772908b465',
  (SELECT "id" FROM "modelltests" WHERE "number" = 8),
  'LESEN', 2, 'RICHTIG_FALSCH',
  'Lesen', 'Lesen Sie den Text und die Aufgaben 6–10. Sind die Aussagen richtig (+) oder falsch (–)? Kreuzen Sie an.',
  5, 'AUTO', '{"stimulus":{"type":"TEXT","body":"Der deutsche Popsänger Peter Nohlen (48) und seine Patricia (23) werden bald Hochzeit feiern. Darüber freut sich nicht nur Patricia selbst – auch ihre Mutter Maria Luisa García Concha (48) ist erleichtert: „Ich bin froh, dass er sie endlich heiraten will.“\nPatricias Mutter machte sich Sorgen, weil ihre Tochter schon zwei Jahre mit Peter in einem Haus zusammenlebt. Peter ist nach drei gescheiterten Ehen und unzähligen Affären nicht gerade ein Wunschkandidat für Schwiegermütter. Maria Luisa stellte Nachforschungen über den blonden Peter aus Berlin an. Mit positivem Ausgang: „Patricia hat im Leben immer eine gute Wahl getroffen. Wenn sie mit Peter glücklich ist, soll er mir als Schwiegersohn willkommen sein“, so ihre Mutter.\nUnd dann gibt Maria Luisa ihrem Schwiegersohn in spe auch gleich den ersten Rat mit auf den Weg: „Heiraten ist mehr als nur nach Las Vegas fahren. Ich möchte, dass er meine Tochter glücklich macht, und außerdem möchte ich bald Oma werden.“","title":"Peter Nohlen: Hochzeit in Las Vegas"}}'::jsonb,
  'a2-modelltest-1-lesen-teil-2-v1', NULL, 2
);
