  5, 'AUTO', '{"leftLabel":"Situation","rightLabel":"Anzeige","allowNoMatch":true,"noMatchKey":"x","choices":[{"key":"a","title":"www.bahn.de","body":"Genießen Sie schöne Ferien in Deutschland mit uns. Wir bringen Sie in alle Städte. Günstige Ski-Reisen mit Sparmöglichkeiten für Ihre Geldbörse!"},{"key":"b","title":"www.reiserat.com","body":"Reisegebiete, Bundesländer. Flussreisen (Rhein, Main, Donau). Ferienhaus online buchen. Interaktive Deutschlandkarte."},{"key":"c","title":"www.goodjob.de","body":"Auslandsjobs. Weltweit Stellenangebote – für junge Deutsche im Ausland: Festanstellung, Teilzeit, mit freier Zeiteinteilung. Auch Schüler- und Studentenjobs."},{"key":"d","title":"www.schneider.de","body":"Dr. Schneiders Sprachreisen. Ihr Spezialist für erfolgreiche Sprach-Weiterbildung in: Großbritannien, Portugal, Spanien, Frankreich und den USA."},{"key":"e","title":"www.sprachtreff.de","body":"SPRACHTREFF. Sprachreisen, Sprachkurse für Erwachsene und Schüler, Schülersprachreisen in Deutschland und aller Welt. Dazu viele Freizeitangebote."},{"key":"f","title":"Urlaub in Deutschland","body":"Luxus-Hotels. Ferienwohnungen und Ferienhäuser. Mietwagen mit Fahrer. Gehobene internationale Gastronomie. Infos unter www.inforeisen.de"},{"key":"g","title":"Billig reisen","body":"Online-Preisvergleich aller Anbieter für Deutschland-Reisen. Kurzurlaub, Rundreisen mit Pkw oder Caravan, Ferienhäuser/Ferienwohnungen, Mietwagen. www.inforeisen.de"},{"key":"h","title":"www.germanembassy-india.org","body":"Arbeiten in Deutschland. Zollvorschriften. Studieren in Deutschland. Schüler- und Jugendaustausch."}]}'::jsonb,
  'a2-modelltest-1-lesen-teil-3-v1', NULL, 3
);
